import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.util.CheckDigit;
import org.springframework.stereotype.Component;

/**
 * Populates the read-only {@code checkDigit} on an owner response: the Luhn check digit over the
 * digits of the owner's {@code customerCode}. Derived on the way out from the owner's own fields,
 * so it never affects storage or the request.
 */
@Aspect
@Component
public class OwnerCheckDigitAdvice {

    @AfterReturning(pointcut = "execution(* org.springframework.samples.petclinic.rest.controller.v1."
        + "OwnerRestControllerV1.addOwner(..)) || execution(* org.springframework.samples.petclinic.rest."
        + "controller.v1.OwnerRestControllerV1.getOwner(..))", returning = "response")
    public void addCheckDigit(ResponseEntity<?> response) {
        Object body = response == null ? null : response.getBody();
        if (body instanceof OwnerDto owner && owner.getCustomerCode() != null) {
            owner.setCheckDigit(CheckDigit.luhn(owner.getCustomerCode()));
        }
    }
}

